// src/releaseNotice.ts
function getReleaseNote(version) {
  return ARBOR_RELEASE_NOTES.find((note) => note.version === version);
}
function shouldShowReleaseNotice(lastSeenVersion, currentVersion, isFreshInstall) {
  if (isFreshInstall || !getReleaseNote(currentVersion)) {
    return false;
  }
  return !lastSeenVersion || compareSemver(lastSeenVersion, currentVersion) < 0;
}
function compareSemver(left, right) {
  const leftParts = left.split(".").map((part) => Number.parseInt(part, 10));
  const rightParts = right.split(".").map((part) => Number.parseInt(part, 10));
  const length = Math.max(leftParts.length, rightParts.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (leftParts[index] ?? 0) - (rightParts[index] ?? 0);
    if (difference !== 0) {
      return difference;
    }
  }
  return 0;
}

